-- Newsletter DRAFTS generated by scripts/newsletter-drafts/build.mts.
-- Inserts as status 'draft' / stage 'early'; nothing here schedules or sends.
-- Skips any draft whose title already exists. Safe to re-run.

-- signal-photos-live
insert into public.newsletters
  (title, subject, preheader, audience, blocks, status, stage)
select
  'Signal photos + all partners',
  '📸 The Signal photos are here',
  '320 photos from the afternoon, ready to browse and download.',
  'subscribers',
  $nl$[{"id":"signal-photos-live-01","type":"header","text":"The Signal photos are here.","size":"lg"},{"id":"signal-photos-live-02","type":"image","src":"https://tedxnewy.com.au/images/newsletter/signal-photos-collage.jpg","alt":"A collage of photos from Signal: the TEDxNewy stage, a guest celebrating, an applauding audience and two friends on the balcony","widthPct":"full","href":"https://tedxnewy.com.au/signal"},{"id":"signal-photos-live-03","type":"text","html":"<p>320 photos from Signal are now live on our website, captured on the day by our media partner Newy Digital.</p><p>Find yourself, your friends or your favourite moment from the afternoon, then browse and download the full set.</p>"},{"id":"signal-photos-live-04","type":"button","label":"See the Signal photos","href":"https://tedxnewy.com.au/signal","align":"center","theme":"red","variant":"solid"},{"id":"signal-photos-live-05","type":"text","html":"<p>The talks are next. We'll add each video to the same page as it goes live, so keep an eye on it.</p>"},{"id":"signal-photos-live-06","type":"divider","style":"short","colour":"soft"},{"id":"signal-photos-live-07","type":"header","text":"Thank you to our activating partners","size":"md"},{"id":"signal-photos-live-08","type":"text","html":"<p>Activation Alley was a big part of what made Signal feel alive, and that was down to these partners. Thank you for giving your time, your ideas and your energy to the day.</p>"},{"id":"signal-photos-live-11","type":"header","text":"Henderson","size":"md"},{"id":"signal-photos-live-12","type":"columns","cols":[[{"id":"signal-photos-live-09","kind":"image","src":"https://tedxnewy.com.au/images/newsletter/signal-partner-henderson.jpg","alt":"Henderson merchandise on the Henderson stall at Signal","widthPct":100}],[{"id":"signal-photos-live-10","kind":"text","html":"<p>Thank you for bringing your stall to Activation Alley.</p><p><a href=\"https://henderson.com.au\">Visit Henderson</a></p>"}]],"ratio":"40-60","valign":"middle","mobileOrder":"imageFirst"},{"id":"signal-photos-live-15","type":"header","text":"Sketch It Live","size":"md"},{"id":"signal-photos-live-16","type":"columns","cols":[[{"id":"signal-photos-live-14","kind":"text","html":"<p>Thank you for capturing the day in live graphic recordings.</p><p><a href=\"http://sketchitlive.com.au\">Visit Sketch It Live</a></p>"}],[{"id":"signal-photos-live-13","kind":"image","src":"https://tedxnewy.com.au/images/newsletter/signal-partner-sketch-it-live.jpg","alt":"A Sketch It Live graphic recording of Signal on a desk","widthPct":100}]],"ratio":"60-40","valign":"middle","mobileOrder":"imageFirst"},{"id":"signal-photos-live-19","type":"header","text":"Ink and Snow","size":"md"},{"id":"signal-photos-live-20","type":"columns","cols":[[{"id":"signal-photos-live-17","kind":"image","src":"https://tedxnewy.com.au/images/newsletter/signal-partner-ink-and-snow.jpg","alt":"An Ink and Snow artist painting a live watercolour portrait","widthPct":100}],[{"id":"signal-photos-live-18","kind":"text","html":"<p>Thank you for painting live watercolour portraits for guests in the foyer.</p><p><a href=\"https://www.inkandsnow.com\">Visit Ink and Snow</a></p>"}]],"ratio":"40-60","valign":"middle","mobileOrder":"imageFirst"},{"id":"signal-photos-live-23","type":"header","text":"Talk2MeBro","size":"md"},{"id":"signal-photos-live-24","type":"columns","cols":[[{"id":"signal-photos-live-22","kind":"text","html":"<p>Thank you for bringing your merch and information stand to Activation Alley.</p><p><a href=\"https://www.talk2mebro.org.au\">Visit Talk2MeBro</a></p>"}],[{"id":"signal-photos-live-21","kind":"image","src":"https://tedxnewy.com.au/images/newsletter/signal-partner-talk2mebro.jpg","alt":"Talk2MeBro merchandise on the Talk2MeBro stand","widthPct":100}]],"ratio":"60-40","valign":"middle","mobileOrder":"imageFirst"},{"id":"signal-photos-live-27","type":"header","text":"New Artists Collective","size":"md"},{"id":"signal-photos-live-28","type":"columns","cols":[[{"id":"signal-photos-live-25","kind":"image","src":"","alt":"New Artists Collective at Signal","widthPct":100}],[{"id":"signal-photos-live-26","kind":"text","html":"<p>Thank you for bringing a mini-gallery of artwork to the foyer.</p><p><a href=\"https://www.newartistscollective.com\">Visit New Artists Collective</a></p>"}]],"ratio":"40-60","valign":"middle","mobileOrder":"imageFirst"},{"id":"signal-photos-live-31","type":"header","text":"Akrue","size":"md"},{"id":"signal-photos-live-32","type":"columns","cols":[[{"id":"signal-photos-live-30","kind":"text","html":"<p>Thank you for joining us in Activation Alley.</p><p><a href=\"https://akrue.com.au\">Visit Akrue</a></p>"}],[{"id":"signal-photos-live-29","kind":"image","src":"https://tedxnewy.com.au/images/newsletter/signal-partner-akrue.jpg","alt":"Akrue flyers and stickers on the Akrue stall","widthPct":100}]],"ratio":"60-40","valign":"middle","mobileOrder":"imageFirst"},{"id":"signal-photos-live-35","type":"header","text":"InHouse Plants","size":"md"},{"id":"signal-photos-live-36","type":"columns","cols":[[{"id":"signal-photos-live-33","kind":"image","src":"https://tedxnewy.com.au/images/newsletter/signal-partner-inhouse-plants.jpg","alt":"Guests potting plants at the InHouse Plants activation","widthPct":100}],[{"id":"signal-photos-live-34","kind":"text","html":"<p>Thank you for joining us in Activation Alley.</p><p><a href=\"https://www.inhouseplants.com.au\">Visit InHouse Plants</a></p>"}]],"ratio":"40-60","valign":"middle","mobileOrder":"imageFirst"},{"id":"signal-photos-live-39","type":"header","text":"The Bridge Project","size":"md"},{"id":"signal-photos-live-40","type":"columns","cols":[[{"id":"signal-photos-live-38","kind":"text","html":"<p>Thank you for joining us in Activation Alley.</p><p><a href=\"https://www.thebridgeproject.com.au\">Visit The Bridge Project</a></p>"}],[{"id":"signal-photos-live-37","kind":"image","src":"","alt":"The Bridge Project at Signal","widthPct":100}]],"ratio":"60-40","valign":"middle","mobileOrder":"imageFirst"},{"id":"signal-photos-live-43","type":"header","text":"Lefthand Design","size":"md"},{"id":"signal-photos-live-44","type":"columns","cols":[[{"id":"signal-photos-live-41","kind":"image","src":"","alt":"Lefthand Design at Signal","widthPct":100}],[{"id":"signal-photos-live-42","kind":"text","html":"<p>Thank you for joining us in Activation Alley.</p><p><a href=\"https://left-handesign.com\">Visit Lefthand Design</a></p>"}]],"ratio":"40-60","valign":"middle","mobileOrder":"imageFirst"},{"id":"signal-photos-live-47","type":"header","text":"Bandigon","size":"md"},{"id":"signal-photos-live-48","type":"columns","cols":[[{"id":"signal-photos-live-46","kind":"text","html":"<p>Thank you for joining us in Activation Alley.</p><p><a href=\"https://bandigon.com\">Visit Bandigon</a></p>"}],[{"id":"signal-photos-live-45","kind":"image","src":"","alt":"Bandigon at Signal","widthPct":100}]],"ratio":"60-40","valign":"middle","mobileOrder":"imageFirst"},{"id":"signal-photos-live-51","type":"header","text":"Cherry","size":"md"},{"id":"signal-photos-live-52","type":"columns","cols":[[{"id":"signal-photos-live-49","kind":"image","src":"","alt":"Cherry at Signal","widthPct":100}],[{"id":"signal-photos-live-50","kind":"text","html":"<p>Thank you for joining us in Activation Alley.</p><p><a href=\"https://www.cherrypi.io/about\">Visit Cherry</a></p>"}]],"ratio":"40-60","valign":"middle","mobileOrder":"imageFirst"},{"id":"signal-photos-live-55","type":"header","text":"Meandrix","size":"md"},{"id":"signal-photos-live-56","type":"columns","cols":[[{"id":"signal-photos-live-54","kind":"text","html":"<p>Thank you for joining us in Activation Alley.</p><p><a href=\"https://www.meandrix.com\">Visit Meandrix</a></p>"}],[{"id":"signal-photos-live-53","kind":"image","src":"","alt":"Meandrix at Signal","widthPct":100}]],"ratio":"60-40","valign":"middle","mobileOrder":"imageFirst"},{"id":"signal-photos-live-57","type":"divider","style":"short","colour":"soft"},{"id":"signal-photos-live-58","type":"text","html":"<p>Thank you for being part of Signal.</p><p>Will and the TEDxNewy team</p>"}]$nl$::jsonb,
  'draft',
  'early'
where not exists (
  select 1 from public.newsletters where title = 'Signal photos + all partners'
);
